css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .84); position: relative; }
.loader::after { content: ''; position: absolute; bottom: 0; left: 46%; width: 8%; height: 56%; border-radius: 4px; background: linear-gradient(var(--accent), color-mix(in srgb, #000 24%, var(--accent))); }
.loader::before { content: ''; position: absolute; bottom: 2%; left: 26%; width: 48%; height: 10%; border-radius: 50% 50% 40% 40%; background: color-mix(in srgb, #000 18%, var(--accent)); }
.loader span { position: absolute; bottom: 50%; width: 40%; height: 40%; background: linear-gradient(color-mix(in srgb, #fff 20%, var(--accent-2)), var(--accent-2)); box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 28%, var(--accent-2)); }
.loader span:nth-child(1) { right: 50%; transform-origin: bottom right; border-radius: 84% 12% 10% 62%; animation: snap-left calc(var(--loader-speed) * 2.4) cubic-bezier(.55, 0, .2, 1) infinite; }
.loader span:nth-child(2) { left: 50%; transform-origin: bottom left; border-radius: 12% 84% 62% 10%; animation: snap-right calc(var(--loader-speed) * 2.4) cubic-bezier(.55, 0, .2, 1) infinite; }
@keyframes snap-left { 0%, 38% { transform: rotate(-34deg); } 50%, 68% { transform: rotate(-3deg); } 88%, 100% { transform: rotate(-34deg); } }
@keyframes snap-right { 0%, 38% { transform: rotate(34deg); } 50%, 68% { transform: rotate(3deg); } 88%, 100% { transform: rotate(34deg); } }
